// Bakes content/docs/*.md into src/app/docs/docs.generated.ts, so the docs pages need no
// file system at runtime (Cloudflare Workers have none). Runs before every build; a test
// fails if the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = join(import.meta.dirname, "..", "content", "docs");
const files = readdirSync(dir).filter((f) => f.endsWith(".md")).sort();
const body = files.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(join(dir, f), "utf8"))},`).join("\n");
const out = `// Generated by scripts/gen-docs.mjs from content/docs/*.md. Don't edit; run \`npm run docs:gen\`.\nexport const DOCS: Record<string, string> = {\n${body}\n};\n`;
writeFileSync(join(import.meta.dirname, "..", "src", "app", "docs", "docs.generated.ts"), out);
